package com.logatron.integration;
import com.logatron.audit.persistence.AuditEventRepository;import com.logatron.catalog.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true) @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="spring.profiles.active=dev-auth")
class PostgresIntegrationTest{static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:17.6-alpine").withDatabaseName("logatron").withUsername("logatron").withPassword("test-password");@Container static final PostgreSQLContainer<?> CONTAINER=POSTGRES;@DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);}@Autowired ProjectRepository projects;@Autowired EnvironmentRepository environments;@Autowired AuditEventRepository audit;@Test void flywaySeedsCatalogAndRepositories(){assertThat(projects.count()).isEqualTo(4);assertThat(environments.findByProjectIdOrderByCode(UUID.fromString("10000000-0000-0000-0000-000000000001"))).hasSize(3);assertThat(audit.count()).isZero();}}
